import { useEffect, useState } from 'react';
import { useLocation, useParams } from 'react-router-dom';

import { Breadcrumbs } from 'components/Breadcrumbs';
import { PageHeader } from 'components/PageHeader';
import { StyledGridContainer, StyledHomeHeaderContainer } from 'shared/Styles';

import { MediaViewer } from '../../components';
import { Training, TrainingContentType, TrainingHubData } from '../../domain';
import { useRecentTrainings, useTrainingData } from '../../hooks';
import {
  StyledTrainingHubHome,
  StyledTrainingHubWrapper,
} from '../Home/Home.styles';

export const TrainingPage = () => {
  const [pageList, setPageList] = useState<
    { pageName: string; href: string }[]
  >([]);
  const { addRecentTraining } = useRecentTrainings();
  const { trainingData, getTraining } = useTrainingData();
  const { pillar, id } = useParams();
  const location = useLocation();
  const fromRecentlyAdded =
    (location.state as { from?: string } | null)?.from === 'recently-added';

  const training = getTraining(pillar as string, id as string);

  const getPageList = () => {
    const homePage = { pageName: 'Training Hub', href: '/training-hub' };
    const trainingPage = {
      pageName: 'Training Page',
      href: `/training-hub/training/${id}`,
    };
    const recentlyAddedPage = {
      pageName: 'Recently Added',
      href: '/training-hub/recently-added',
    };
    const pillarName =
      trainingData[pillar as keyof TrainingHubData]?.name || '';
    const pillarPage = {
      pageName: pillarName,
      href: `/training-hub/${pillar}`,
    };

    if (pillar) {
      return [homePage, pillarPage, trainingPage];
    }

    if (fromRecentlyAdded) {
      return [homePage, recentlyAddedPage, trainingPage];
    }

    return [homePage, trainingPage];
  };

  useEffect(() => {
    setPageList(getPageList());
    if (training) {
      addRecentTraining(training as Training);
    }
  }, [setPageList, addRecentTraining, training, pillar, id, fromRecentlyAdded]);

  return (
    <StyledGridContainer>
      <StyledTrainingHubWrapper>
        <StyledTrainingHubHome>
          <Breadcrumbs pageList={pageList} showIcon={true} />
          <StyledHomeHeaderContainer>
            <PageHeader
              title="Training Page"
              subtitle="Access the learning and training materials for the One Way platform."
            />
          </StyledHomeHeaderContainer>
          {training?.content.map((content: string) => (
            <MediaViewer
              key={content}
              media={content}
              type={training?.type as TrainingContentType}
              title={training?.title}
            />
          ))}
        </StyledTrainingHubHome>
      </StyledTrainingHubWrapper>
    </StyledGridContainer>
  );
};
